import { db } from "@orksys-survey/db";
import {
	answer,
	logicRule,
	question,
	response,
	survey,
} from "@orksys-survey/db/schema/survey";
import { and, count, desc, eq, inArray } from "drizzle-orm";
import { z } from "zod";

import {
	adminProcedure,
	organizationProcedure,
	publicProcedure,
} from "../index";

// Input schemas
const submitResponseSchema = z.object({
	surveyId: z.string(),
	fingerprint: z.string().optional(),
	respondentId: z.string().optional(),
	metadata: z
		.object({
			userAgent: z.string().optional(),
			referrer: z.string().optional(),
			browser: z.string().optional(),
			os: z.string().optional(),
			device: z.string().optional(),
			country: z.string().optional(),
			language: z.string().optional(),
			timezone: z.string().optional(),
		})
		.optional(),
	answers: z.array(
		z.object({
			questionId: z.string(),
			value: z.unknown(),
		}),
	),
	isComplete: z.boolean().default(false),
});

const responseListSchema = z.object({
	surveyId: z.string(),
	page: z.number().int().min(1).default(1),
	limit: z.number().int().min(1).max(100).default(20),
	isComplete: z.boolean().optional(),
});

// Generate unique IDs
function generateResponseId(): string {
	return `resp_${Date.now()}_${Math.random().toString(36).substring(2, 11)}`;
}

function generateAnswerId(): string {
	return `ans_${Date.now()}_${Math.random().toString(36).substring(2, 11)}`;
}

// Verify survey belongs to organization
async function verifySurveyAccess(
	surveyId: string,
	organizationId: string,
): Promise<void> {
	const result = await db
		.select()
		.from(survey)
		.where(
			and(eq(survey.id, surveyId), eq(survey.organizationId, organizationId)),
		)
		.limit(1);

	if (!result[0]) {
		throw new Error("Survey not found");
	}
}

export const responseRouter = {
	// PUBLIC - Get published survey for runner
	getSurveyForRunner: publicProcedure
		.input(z.object({ slug: z.string() }))
		.handler(async ({ input }) => {
			const surveyResult = await db
				.select()
				.from(survey)
				.where(and(eq(survey.slug, input.slug), eq(survey.status, "published")))
				.limit(1);

			if (!surveyResult[0]) {
				throw new Error("Survey not found or not published");
			}

			// Get questions and logic rules for the survey in parallel
			const [questions, logicRules] = await Promise.all([
				db
					.select()
					.from(question)
					.where(eq(question.surveyId, surveyResult[0].id))
					.orderBy(question.order),
				db
					.select()
					.from(logicRule)
					.where(eq(logicRule.surveyId, surveyResult[0].id)),
			]);

			return {
				survey: surveyResult[0],
				questions,
				logicRules,
			};
		}),

	// PUBLIC - Submit response
	submit: publicProcedure
		.input(submitResponseSchema)
		.handler(async ({ input }) => {
			// Verify survey exists and is published
			const surveyResult = await db
				.select()
				.from(survey)
				.where(
					and(eq(survey.id, input.surveyId), eq(survey.status, "published")),
				)
				.limit(1);

			if (!surveyResult[0]) {
				throw new Error("Survey not found or not published");
			}

			// Check for duplicate fingerprint if provided and multiple responses NOT allowed
			if (
				input.fingerprint &&
				!surveyResult[0].settings?.allowMultipleResponses
			) {
				const existingResponse = await db
					.select()
					.from(response)
					.where(
						and(
							eq(response.surveyId, input.surveyId),
							eq(response.fingerprint, input.fingerprint),
						),
					)
					.limit(1);

				if (existingResponse[0]) {
					throw new Error("You have already responded to this survey");
				}
			}

			// Verify all questions belong to this survey
			const questionIds = input.answers.map((a) => a.questionId);
			if (questionIds.length > 0) {
				const questions = await db
					.select()
					.from(question)
					.where(inArray(question.id, questionIds));

				for (const q of questions) {
					if (q.surveyId !== input.surveyId) {
						throw new Error(`Question ${q.id} does not belong to this survey`);
					}
				}
			}

			// Create response and answers in a transaction
			const responseId = generateResponseId();
			const now = new Date();

			await db.insert(response).values({
				id: responseId,
				surveyId: input.surveyId,
				respondentId: input.respondentId ?? null,
				fingerprint: input.fingerprint ?? null,
				metadata: input.metadata ?? null,
				isComplete: input.isComplete,
				startedAt: now,
				completedAt: input.isComplete ? now : null,
			});

			// Insert answers
			if (input.answers.length > 0) {
				const answersToInsert = input.answers.map((a) => ({
					id: generateAnswerId(),
					responseId,
					questionId: a.questionId,
					value: a.value,
				}));

				await db.insert(answer).values(answersToInsert);
			}

			return { success: true, responseId };
		}),

	// PROTECTED - List responses for a survey
	list: organizationProcedure
		.input(responseListSchema)
		.handler(async ({ input, context }) => {
			await verifySurveyAccess(input.surveyId, context.activeOrganization.id);

			const { page, limit, surveyId, isComplete } = input;
			const offset = (page - 1) * limit;

			const conditions = [eq(response.surveyId, surveyId)];
			if (isComplete !== undefined) {
				conditions.push(eq(response.isComplete, isComplete));
			}

			const [responses, totalResult] = await Promise.all([
				db
					.select()
					.from(response)
					.where(and(...conditions))
					.orderBy(desc(response.createdAt))
					.limit(limit)
					.offset(offset),
				db
					.select({ count: count() })
					.from(response)
					.where(and(...conditions)),
			]);

			return {
				data: responses,
				pagination: {
					page,
					limit,
					total: totalResult[0]?.count ?? 0,
					totalPages: Math.ceil((totalResult[0]?.count ?? 0) / limit),
				},
			};
		}),

	// PROTECTED - Get single response with answers
	getById: organizationProcedure
		.input(z.object({ id: z.string() }))
		.handler(async ({ input, context }) => {
			const result = await db
				.select()
				.from(response)
				.where(eq(response.id, input.id))
				.limit(1);

			if (!result[0]) {
				throw new Error("Response not found");
			}

			// Verify survey access
			await verifySurveyAccess(
				result[0].surveyId,
				context.activeOrganization.id,
			);

			// Get answers - we'd need an answer table query here
			// For now, return the response without answers
			return result[0];
		}),

	// PROTECTED - Get response stats for a survey
	getStats: organizationProcedure
		.input(z.object({ surveyId: z.string() }))
		.handler(async ({ input, context }) => {
			await verifySurveyAccess(input.surveyId, context.activeOrganization.id);

			const [totalResult, completeResult, partialResult] = await Promise.all([
				db
					.select({ count: count() })
					.from(response)
					.where(eq(response.surveyId, input.surveyId)),
				db
					.select({ count: count() })
					.from(response)
					.where(
						and(
							eq(response.surveyId, input.surveyId),
							eq(response.isComplete, true),
						),
					),
				db
					.select({ count: count() })
					.from(response)
					.where(
						and(
							eq(response.surveyId, input.surveyId),
							eq(response.isComplete, false),
						),
					),
			]);

			return {
				total: totalResult[0]?.count ?? 0,
				complete: completeResult[0]?.count ?? 0,
				partial: partialResult[0]?.count ?? 0,
			};
		}),

	// PROTECTED - Delete single response
	delete: adminProcedure
		.input(z.object({ id: z.string() }))
		.handler(async ({ input, context }) => {
			const result = await db
				.select()
				.from(response)
				.where(eq(response.id, input.id))
				.limit(1);

			if (!result[0]) {
				throw new Error("Response not found");
			}

			await verifySurveyAccess(
				result[0].surveyId,
				context.activeOrganization.id,
			);

			await db.delete(response).where(eq(response.id, input.id));
			return { success: true };
		}),

	// PROTECTED - Bulk delete responses
	bulkDelete: adminProcedure
		.input(z.object({ ids: z.array(z.string()) }))
		.handler(async ({ input, context }) => {
			if (input.ids.length === 0) {
				return { success: true, deletedCount: 0 };
			}

			const responses = await db
				.select()
				.from(response)
				.where(inArray(response.id, input.ids));

			if (responses.length !== input.ids.length) {
				throw new Error("Some responses not found");
			}

			// Verify survey access for first response
			const firstResponse = responses[0];
			if (!firstResponse) {
				throw new Error("No responses found");
			}
			await verifySurveyAccess(
				firstResponse.surveyId,
				context.activeOrganization.id,
			);

			await db.delete(response).where(inArray(response.id, input.ids));

			return { success: true, deletedCount: responses.length };
		}),
};

import { relations } from "drizzle-orm";
import {
	boolean,
	index,
	integer,
	json,
	pgEnum,
	pgTable,
	text,
	timestamp,
	uniqueIndex,
} from "drizzle-orm/pg-core";
import { user } from "./auth";
import { organization } from "./organization";

// Survey status enum
export const surveyStatusEnum = pgEnum("survey_status", [
	"draft",
	"published",
	"closed",
	"archived",
]);

// Question type enum
export const questionTypeEnum = pgEnum("question_type", [
	"text",
	"textarea",
	"multiple_choice",
	"checkbox",
	"dropdown",
	"rating",
	"nps",
	"linear_scale",
	"date",
	"email",
	"phone",
	"file_upload",
]);

// Logic operator enum
export const logicOperatorEnum = pgEnum("logic_operator", [
	"equals",
	"not_equals",
	"contains",
	"greater_than",
	"less_than",
	"is_empty",
	"is_not_empty",
]);

// Logic action enum
export const logicActionEnum = pgEnum("logic_action", [
	"jump_to",
	"skip",
	"show",
	"hide",
	"end_survey",
]);

// Survey table
export const survey = pgTable(
	"survey",
	{
		id: text("id").primaryKey(),
		slug: text("slug").notNull(),
		title: text("title").notNull(),
		description: text("description"),
		status: surveyStatusEnum("status").default("draft").notNull(),
		settings: json("settings").$type<SurveySettings>(),
		userId: text("user_id")
			.notNull()
			.references(() => user.id, { onDelete: "cascade" }),
		organizationId: text("organization_id")
			.notNull()
			.references(() => organization.id, { onDelete: "cascade" }),
		createdAt: timestamp("created_at").defaultNow().notNull(),
		updatedAt: timestamp("updated_at")
			.defaultNow()
			.$onUpdate(() => new Date())
			.notNull(),
	},
	(table) => [
		uniqueIndex("survey_slug_idx").on(table.slug),
		index("survey_organizationId_idx").on(table.organizationId),
		index("survey_userId_idx").on(table.userId),
		index("survey_status_idx").on(table.status),
	],
);

// Question table
export const question = pgTable(
	"question",
	{
		id: text("id").primaryKey(),
		surveyId: text("survey_id")
			.notNull()
			.references(() => survey.id, { onDelete: "cascade" }),
		type: questionTypeEnum("type").notNull(),
		title: text("title").notNull(),
		description: text("description"),
		config: json("config").$type<QuestionConfig>(),
		required: boolean("required").default(false).notNull(),
		order: integer("order").default(0).notNull(),
		createdAt: timestamp("created_at").defaultNow().notNull(),
		updatedAt: timestamp("updated_at")
			.defaultNow()
			.$onUpdate(() => new Date())
			.notNull(),
	},
	(table) => [
		index("question_surveyId_idx").on(table.surveyId),
		index("question_order_idx").on(table.order),
	],
);

// Logic rule table
export const logicRule = pgTable(
	"logic_rule",
	{
		id: text("id").primaryKey(),
		surveyId: text("survey_id")
			.notNull()
			.references(() => survey.id, { onDelete: "cascade" }),
		sourceQuestionId: text("source_question_id")
			.notNull()
			.references(() => question.id, { onDelete: "cascade" }),
		operator: logicOperatorEnum("operator").notNull(),
		conditionValue: json("condition_value").$type<unknown>(),
		action: logicActionEnum("action").notNull(),
		targetQuestionId: text("target_question_id").references(() => question.id, {
			onDelete: "set null",
		}),
		createdAt: timestamp("created_at").defaultNow().notNull(),
		updatedAt: timestamp("updated_at")
			.defaultNow()
			.$onUpdate(() => new Date())
			.notNull(),
	},
	(table) => [
		index("logicRule_surveyId_idx").on(table.surveyId),
		index("logicRule_sourceQuestionId_idx").on(table.sourceQuestionId),
	],
);

// Response table
export const response = pgTable(
	"response",
	{
		id: text("id").primaryKey(),
		surveyId: text("survey_id")
			.notNull()
			.references(() => survey.id, { onDelete: "cascade" }),
		respondentId: text("respondent_id"),
		fingerprint: text("fingerprint"),
		metadata: json("metadata").$type<ResponseMetadata>(),
		isComplete: boolean("is_complete").default(false).notNull(),
		startedAt: timestamp("started_at").defaultNow().notNull(),
		completedAt: timestamp("completed_at"),
		createdAt: timestamp("created_at").defaultNow().notNull(),
		updatedAt: timestamp("updated_at")
			.defaultNow()
			.$onUpdate(() => new Date())
			.notNull(),
	},
	(table) => [
		index("response_surveyId_idx").on(table.surveyId),
		index("response_fingerprint_idx").on(table.fingerprint),
		index("response_isComplete_idx").on(table.isComplete),
	],
);

// Answer table
export const answer = pgTable(
	"answer",
	{
		id: text("id").primaryKey(),
		responseId: text("response_id")
			.notNull()
			.references(() => response.id, { onDelete: "cascade" }),
		questionId: text("question_id")
			.notNull()
			.references(() => question.id, { onDelete: "cascade" }),
		value: json("value").$type<unknown>(),
		createdAt: timestamp("created_at").defaultNow().notNull(),
		updatedAt: timestamp("updated_at")
			.defaultNow()
			.$onUpdate(() => new Date())
			.notNull(),
	},
	(table) => [
		index("answer_responseId_idx").on(table.responseId),
		index("answer_questionId_idx").on(table.questionId),
	],
);

// Relations
export const surveyRelations = relations(survey, ({ one, many }) => ({
	organization: one(organization, {
		fields: [survey.organizationId],
		references: [organization.id],
	}),
	owner: one(user, {
		fields: [survey.userId],
		references: [user.id],
	}),
	questions: many(question),
	responses: many(response),
	logicRules: many(logicRule),
}));

export const questionRelations = relations(question, ({ one, many }) => ({
	survey: one(survey, {
		fields: [question.surveyId],
		references: [survey.id],
	}),
	answers: many(answer),
	sourceLogicRules: many(logicRule, {
		relationName: "sourceQuestion",
	}),
	targetLogicRules: many(logicRule, {
		relationName: "targetQuestion",
	}),
}));

export const logicRuleRelations = relations(logicRule, ({ one }) => ({
	survey: one(survey, {
		fields: [logicRule.surveyId],
		references: [survey.id],
	}),
	sourceQuestion: one(question, {
		fields: [logicRule.sourceQuestionId],
		references: [question.id],
		relationName: "sourceQuestion",
	}),
	targetQuestion: one(question, {
		fields: [logicRule.targetQuestionId],
		references: [question.id],
		relationName: "targetQuestion",
	}),
}));

export const responseRelations = relations(response, ({ one, many }) => ({
	survey: one(survey, {
		fields: [response.surveyId],
		references: [survey.id],
	}),
	answers: many(answer),
}));

export const answerRelations = relations(answer, ({ one }) => ({
	response: one(response, {
		fields: [answer.responseId],
		references: [response.id],
	}),
	question: one(question, {
		fields: [answer.questionId],
		references: [question.id],
	}),
}));

// Type definitions for JSON fields
export interface SurveySettings {
	showProgressBar?: boolean;
	showQuestionNumbers?: boolean;
	shuffleQuestions?: boolean;
	allowMultipleResponses?: boolean;
	requireAuth?: boolean;
	collectMetadata?: boolean;
	thankYouMessage?: string;
	redirectUrl?: string;
	displayMode?: "one_at_a_time" | "list";
	theme?: {
		primaryColor?: string;
		backgroundColor?: string;
		fontFamily?: string;
	};
}

export interface QuestionConfig {
	placeholder?: string;
	minLength?: number;
	maxLength?: number;
	options?: Array<{ label: string; value: string }>;
	min?: number;
	max?: number;
	step?: number;
	allowOther?: boolean;
	allowMultiple?: boolean;
	maxFiles?: number;
	maxFileSize?: number;
	acceptedFileTypes?: string[];
}

export interface ResponseMetadata {
	userAgent?: string;
	ipAddress?: string;
	referrer?: string;
	browser?: string;
	os?: string;
	device?: string;
	country?: string;
	language?: string;
	timezone?: string;
}

import { createEnv } from "@t3-oss/env-core";
import { z } from "zod";

export const env = createEnv({
	server: {
		DATABASE_URL: z.string().min(1),
		BETTER_AUTH_SECRET: z.string().min(32),
		BETTER_AUTH_URL: z.url(),
		POLAR_ACCESS_TOKEN: z.string().optional(),
		POLAR_SUCCESS_URL: z.url(),
		CORS_ORIGIN: z.url(),
		NODE_ENV: z
			.enum(["development", "production", "test"])
			.default("development"),
	},
	runtimeEnv: process.env,
	emptyStringAsUndefined: true,
});

