	totalResponses: number;
	completeResponses: number;
	partialResponses: number;
	completionRate: number;
	averageTimeSeconds: number | null;
}

export interface QuestionAnalytics {
	questionId: string;
	questionType: string;
	questionTitle: string;
	totalAnswers: number;
	distribution: Array<{
		value: string;
		count: number;
		percentage: number;
	}>;
	// For numeric questions
	average?: number;
	min?: number;
	max?: number;
	// For text questions
	sampleResponses?: string[];
}

export interface TrendDataPoint {
	date: string;
	responses: number;
	completions: number;
}

export interface DemographicsData {
	browsers: Array<{ name: string; count: number; percentage: number }>;
	devices: Array<{ name: string; count: number; percentage: number }>;
	os: Array<{ name: string; count: number; percentage: number }>;
	countries: Array<{ name: string; count: number; percentage: number }>;
}

// AI Analysis data types
export interface TextSummaryAnalysis {
	bullets: string[];
	totalResponses: number;
}

export interface SentimentAnalysis {
	positive: number;
	neutral: number;
	negative: number;
	totalResponses: number;
}

export interface KeywordsAnalysis {
	keywords: Array<{
		word: string;
		count: number;
		weight: number;
	}>;
	totalResponses: number;
}

